package calc

// 0x51ee70 item_spell_execution(c, inst, PL): a party member invokes the spell
// stored on an item (record [0x68516c]+id*0x10d, spell byte +0x63). Usability
// is 0x4fac40; the failure risk is 0x51dcd0 (0x4ff410 threshold, class-skill
// deficit 0x4acba0) scaled by 0x501910, +30 for an unidentified item. It fills
// a character source record, plays the item's sound (0x404b50 narrow format
// into the 8-slot ring 0x6ee440), runs 0x4fb4c0 (spcWorld.cast) with the PL
// argument slot as the used-level out, then posts the outcome message
// (0x58ab60 排除 stub, item name from the 0x68c108 word cache) and trains the
// skill (0x4f9ae0 / 0x553f10). D4 callees 0x4fac40 and 0x4f9ae0 are address
// stubs that F runs through spcCallees; 0x501910, 0x4ff410, 0x4acba0, 0x517ec0
// and 0x5905c0(1, -1) run natively.

const (
	ieItems = 4 // fixture cap: item ids below 4 (re/emu/cases/0051ee70.json)
	ieWords = 8 // fixture cap: name-cache words below 8
)

func (w *spcWorld) itemCast(c, inst, pl uint32) uint32 {
	idx := w.ieIndex(c)
	id := w.u32(inst)
	if id >= ieItems {
		spcPanic("51ee70 item id past the fixture item records")
	}
	r := w.u32(0x68516c) + id*0x10d
	spell := uint32(w.u8(r + 0x63))
	class := w.u8(r + 0x3e)
	flag := uint32(0)
	if spell == 0 || class == 0xe || class == 0x15 || class == 0x16 {
		flag = 1
	}
	if byte(w.stub(0x4fac40, idx, spell, pl, 1, flag)) == 0 {
		return 0
	}
	rec := w.spellRecord(spell)
	skill, risk := uint32(0xffffffff), uint32(0)
	if spell != 0x58 && spell != 0x74 {
		kind := uint32(w.u8(r + 0x42))
		if kind >= 12 {
			spcPanic("51ee70 item kind past the 12-entry skill table 0x616e84")
		}
		skill = w.u32(0x616e84 + 4*kind)
	}
	if skill != 0xffffffff {
		risk = w.ieRisk(c, skill, w.u32(c+0x1a3+skill*0x26), spell, pl)
		g := w.u32(0x6836a8) + idx*0xd4 + 0xb4
		risk = uint32(combatSpellRiskPhaseScalingNode([]int64{int64(idx), int64(w.u8(0x683f94)),
			int64(w.u32(0x6850d5)), int64(w.u32(g)), int64(risk)}, nil)[0])
		if w.u8(inst+6) == 0 {
			risk += 0x1e
		}
	}
	src := w.local(0x34)
	marCharSource(w.mcaWorld, idx, src)
	w.put8(src+0x19, 1)
	w.stub(0x501d20, c, spell)
	mode, val := uint32(1), c+0x89
	switch skill {
	case 9:
		mode = 4
	case 0xc:
		mode, val = 2, c+0xb1
	case 0x17:
		mode, val = 3, c+0xad
	}
	w.put8(src+0x1f, byte(w.power(w.u32(val), spell, pl)))
	if w.u8(r+0xe5) != 0 {
		w.stub(0x408860, w.ieSound(r+0xe5), 0)
	}
	tgt := w.u32(0x685178) + idx*0x106 + 0x1d
	used := uint32(mstStackBase + 4 + 4*2) // the PL argument slot
	res := w.cast(spell, src, tgt, pl, 0, risk, 0, used, mode, 0, 0)
	pl = w.u32(used)
	switch res {
	case 1:
		msg := w.u32(w.u32(0x68c09c) + 0x7d0)
		sname := w.u32(0x65be1c) + spell*0x1bf + 0x9b
		if w.u8(0x68510c) != 0 {
			name := r
			if w.u8(inst+6) == 0 {
				name = w.ieName(r)
			}
			w.stub(0x58ab60, 8, 0xffffffff, msg, name, sname, pl)
		} else if w.u8(inst+6) == 0 {
			w.stub(0x58ab60, 8, 0xffffffff, msg, w.ieName(r), sname, pl)
			w.put8(0x69b7b8, 1) // 0x5905c0(1, -1)
		}
		w.put8(inst+7, 1)
	case 3:
		// 0x517a90 formats the 0x51b5c0 text into 0x689fd0 for 0x590950: message
		// text only, left unmodelled as in the 0x58ac00 paths of spcWorld.cast.
		w.stub(0x51b5c0, inst, 0)
		w.notice(idx)
	}
	if skill != 0xffffffff && byte(w.stub(0x4f9ae0, c, spell, tgt, pl)) != 0 {
		w.stub(0x553f10, c, skill, w.u32(rec+0x56)+pl>>1, 0)
	}
	return res
}

// ieIndex is 0x517ec0(c): the party slot of character c (asserts on absence).
func (w *spcWorld) ieIndex(c uint32) uint32 {
	if w.u8(c+4) == 0 {
		spcPanic("517ec0 character not present asserts")
	}
	for i := uint32(0); i < 8; i++ {
		if w.u32(0x685174)+i*0x1862 == c {
			return i
		}
	}
	spcPanic("517ec0 character outside the party asserts")
	return 0
}

// ieRisk is 0x51dcd0(c, skill, v, spell, PL): the item cast failure chance.
func (w *spcWorld) ieRisk(c, skill, v, spell, pl uint32) uint32 {
	rec := w.spellRecord(spell)
	lvl := int32(w.u32(rec+0x49))/2 + int32(w.u32(rec+0x56)) // 0x4ff410
	if lvl > 16 {
		lvl = 16
	}
	if lvl < 0 {
		spcPanic("4ff410 threshold index below table 0x616df0")
	}
	base := uint32(0)
	if m := w.u32(0x616df0+4*uint32(lvl)) * pl / 7; v < m {
		base = (70*m - 70*v) / m
		if int32(base) < 0 {
			base = 0
		} else if base > 100 {
			base = 100
		}
	}
	switch skill {
	case 9:
		return base * 8 / 10
	case 20:
		return base * 9 / 10
	case 12, 23:
		r56 := w.u32(rec + 0x56)
		if q := r56 * 15; v < q {
			base += (q - v) / 3
		}
		if schoolSelectionErr != nil {
			panic(schoolSelectionErr)
		}
		need := uint32(1) // 0x4acba0
		if d := r56 - 2; d < 6 {
			need = uint32(schoolSelectionData.required[d])
		}
		lv := w.u32(c + 0xad)
		if skill == 12 {
			lv = w.u32(c + 0xb1)
		}
		if t := int32(need - lv + pl - 1); t > 0 {
			base += r56 * uint32(t)
		}
	}
	return base
}

// ieSound is 0x404b50: sprintf(0x61aa9c, s) into the next of the eight
// 0x200-byte buffers at 0x6ee440 (ring index 0x650dec).
func (w *spcWorld) ieSound(s uint32) uint32 {
	slot := uint32(w.u8(0x650dec))
	if slot >= 8 {
		spcPanic("404b50 ring index past its 8 buffers")
	}
	next := byte(slot + 1)
	if next == 8 {
		next = 0
	}
	w.put8(0x650dec, next)
	buf := 0x6ee440 + slot*0x200
	str := func(a uint32) []byte {
		var b []byte
		for ; w.u8(a) != 0; a++ {
			b = append(b, w.u8(a))
		}
		return b
	}
	var out []byte
	f := str(0x61aa9c)
	for i := 0; i < len(f); i++ {
		if f[i] != '%' {
			out = append(out, f[i])
			continue
		}
		if i++; i >= len(f) || f[i] != 's' {
			spcPanic("404b50 format directive other than %s")
		}
		out = append(out, str(s)...)
	}
	for i, b := range append(out, 0) {
		w.put8(buf+uint32(i), b)
	}
	return buf
}

// ieName is the unidentified item name: word u16(r+0x3f) formatted once into
// a 0x78-byte heap buffer cached at 0x68c108.
func (w *spcWorld) ieName(r uint32) uint32 {
	k := w.u16(r + 0x3f)
	if k >= ieWords {
		spcPanic("51ee70 item word past the fixture name cache")
	}
	slot := 0x68c108 + 4*k
	if w.u32(slot) == 0 {
		b := w.alloc(0x78)
		w.put32(slot, b)
		t := w.u32(0x68c09c)
		srdPutW(w.mcaWorld, b, srdFormat(w.mcaWorld, w.u32(t+0x79c), w.u32(t+4*w.u16(0x61e810+2*k))))
	}
	return w.u32(slot)
}

func ieBody(w *mcaWorld) {
	s := &spcWorld{mcaWorld: w}
	w.tab = ieStubs
	s.put(mstRet, 4, uint64(s.itemCast(s.arg(0), s.arg(1), s.arg(2))))
}

func itemSpellExecutionNode(in []int64, r Rand) []int64 { return mcaRun(&ieSpec, true, ieBody)(in, r) }

func ieEmu(in []int64, r Rand) []int64 { return mcaRun(&ieSpec, false, ieBody)(in, r) }

func init() {
	Nodes["0051ee70"] = Node{Addr: "0051ee70", In: ieIn, Out: ieOut, F: itemSpellExecutionNode, Emu: ieEmu}
}

